ADM = ['key:Escape', 'user:owner', 'menu:Admin & Setup>Administration']
chapter(23, 'Administration and setup', 'Create a user and a role, switch a sub-function off and on, read the Master configuration and the room master, check approvals, take a backup, read system health, the legacy import and the roadmap.',
        'Sagar (Owner)', 'owner', menu='Admin & Setup')
step('Sagar, the Owner, is on Modules Home. Admin & Setup holds users, roles, settings, backups and system health. Only the Owner and the Tech admin see all of it.', 'What is set here changes the behaviour of every other chapter.', target='sel:.fit-home-grid', auto=['key:Escape', 'user:owner'], action='read', expect='Modules Home for Sagar.', check="ctx.uid==='owner'")
tile('Admin & Setup', 'Click the Admin & Setup tile.', 'The module lists its pages as tiles.', expect='The Admin & Setup page opens.')
read('The tiles are Administration, Approvals & audit, Master configuration, Backup & recovery, System health, Legacy import, Roadmap and Appearance & display. A person with fewer rights sees fewer tiles.', 'The tile list is itself a permission check.', target='sel:main h1', expect='The Admin & Setup tiles.')
leaf('Admin & Setup', 'Administration', 'Click the Administration tile.', 'Users, roles and the module switches are managed here.', expect='Administration opens on the Users tab.', check="ctx.page==='access'")
read('The tabs are Modules & features, Roles, Users and Audit. Users lists the twelve demo users with Edit and Disable. In the production system each user has a PIN or password of their own; the demo has none.', 'Disabling a user stops their access at once and keeps their history.', target='tab:Users', expect='The users list.')
click('btn:New user', 'Click New user. Sunil Pawar joined as a room attendant.', 'A person gets a login only when they need one.', expect='The Create a demo user dialog opens.', check="has('Create user')")
step('Type the name Sunil Pawar and choose the role Housekeeper.', 'The role decides which tiles and which actions the person has.', target='field:Name', auto=['type:field:Name|Sunil Pawar', 'select:field:Role|Housekeeper'], action='type', expect='Name and role filled.')
click('modalbtn:Create user', 'Click Create user.', 'The production server issues a starting PIN that the person must change at the first sign-in; the demo shows none.', expect='The user is created.')
click('tab:Roles', 'Open the Roles tab.', 'Custom roles are built from a base role such as Manager and then adjusted per sub-function: Off, View or Full.', expect='The roles with their permission grids open.')
click('btn:New role', 'Click New role.', 'A hotel can have roles of its own, like the Day shift manager and the Night shift manager already here.', expect='The New custom role dialog opens.', check="has('Create role')")
step('Type the role name Night manager, keep the base role Manager and click Create role.', 'The new role starts as a copy of Manager; the Owner then switches rights off one by one.', target='modalbtn:Create role', auto=['type:field:Role name|Night manager'], action='type', expect='The role name is filled.')
click('modalbtn:Create role', 'Click Create role.', 'The role appears in the list and can be given to users.', expect='The role is created.')
click('tab:Modules & features', 'Open the Modules & features tab.', 'Each module and its sub-functions can be switched off when the hotel does not use them; the data is kept.', expect='The modules and sub-functions are listed with their switches.')
click('btn:Switch off Reservations', 'Click Switch off Reservations.', 'The page and the commands of the sub-function disappear for everybody; core functions such as the folio cannot be switched off.', expect='Reservations is switched off and the data is kept.', msgText='Reservations switched off · data kept')
step('Aarav, the receptionist, opens Front Desk. The Reservations and Calendar tiles are gone; booking commands would be refused.', 'A switched-off sub-function leaves no half-working screen behind.', target='sel:main h1', auto=['key:Escape', 'user:reception', 'click:menutop:Front Desk'], action='click', expect='The Front Desk page has no Reservations or Calendar tile.', check="!has('Reservations')")
step('Sagar opens Modules & features again and clicks Switch on Reservations.', 'Switching on restores the screens at once, with all the data as it was.', target='btn:Switch off Reservations', auto=['key:Escape', 'user:owner', 'menu:Admin & Setup>Administration', 'click:tab:Modules & features', 'click:btn:Switch on Reservations'], action='click', expect='Reservations is on again.')
click('tab:Audit', 'Open the Audit tab.', 'Every change of a role or a switch is a policy version with the user and the time.', expect='The policy versions are listed.')
step('Open Master configuration under Admin & Setup. It holds all the settings of the hotel in twelve groups.', 'Settings are in one place, grouped by the job they belong to.', target='sel:main h1', auto=['menu:Admin & Setup>Master configuration'], action='click', menu='Admin & Setup > Master configuration', expect='Master configuration opens.', check="ctx.page==='settings'")
read('The groups are Property and branding, Rooms and rate plans, Front-desk policies, Money and tax, Restaurant and POS, Housekeeping and maintenance, People, payroll and leave, Compliance obligations, Modules on/off, Users, roles and PINs, Messages and documents, Internet access and Data and system.', 'Each group shows how many settings it holds and the key values.', target='btn:Money and tax', expect='The groups of settings.')
click('btn:Money and tax', 'Click Money and tax.', 'GST rates, currency and rounding are Owner-only: a manager sees them but cannot change them. Rates are dated, so a change from a future date never alters old bills.', expect='The money and tax settings open.')
click('btn:Rooms and rate plans', 'Click Rooms and rate plans.', 'This group holds the masters: floors, amenities, room types, rooms, occupancy charges and meal plans.', expect='The lists of the group open.')
click('btn:Rooms24', 'Click Rooms, 24 rooms.', 'The room master lists every room with the number of stays it has had.', expect='The room master opens with the 24 rooms.')
read('The room master offers Paste rows for a CSV import, Add rooms, Renumber and Set out of order, and the filters Active, Retired and All. Every master of the hotel can be exported and imported as a CSV file from a template.', 'Imports are checked row by row before anything is saved.', target='btn:Paste rows', expect='The room master tools.')
click('btn:203Room 203', 'Click room 203 to open its record.', 'The record holds the type, floor and amenities of the room.', expect='The record of room 203 opens.')
step('Open Internet access in the list of groups.', 'Internet is Off by default; HCC works on the local network and only uses the internet for messages and the booking site if the Owner allows it.', target='btn:Internet access', auto=['key:Escape', 'click:btn:Internet access'], action='click', expect='The Internet access group opens: Internet is Off and guest messaging is Off.')
step('Open Approvals & audit under Admin & Setup and its Audit log tab.', 'The audit log is the record of who did what.', target='tab:Audit log', auto=['menu:Admin & Setup>Approvals & audit', 'click:tab:Audit log'], action='click', menu='Admin & Setup > Approvals & audit', expect='The audit log opens.', check="ctx.page==='approvals'")
step('Open Backup & recovery. Click Run simulated backup.', 'A backup is a copy of the hotel data kept away from the computer; the demo simulates it.', target='btn:Run simulated backup', auto=['menu:Admin & Setup>Backup & recovery'], action='click', menu='Admin & Setup > Backup & recovery', expect='The backup history opens.', check="ctx.page==='backup'")
click('btn:Run simulated backup', 'Click Run simulated backup.', 'The history shows the time and the size; a restore drill proves that a backup can really be restored.', expect='A backup is added to the history.')
click('tab:Restore procedure', 'Open the Restore procedure tab.', 'The seven steps of a restore are written down here and practised once a quarter.', expect='The restore procedure is listed.')
step('Open System health.', 'System health shows stuck background work, the last backups, the internet status and the printers.', target='sel:main h1', auto=['menu:Admin & Setup>System health'], action='click', menu='Admin & Setup > System health', expect='System health opens.', check="ctx.page==='syshealth'")
read('Parked events are jobs that failed and wait for a retry. The page also shows the last backups, the internet (egress) status and the printers with a Print test page button.', 'The Owner and the Tech admin look here when something does not arrive.', target='btn:Retry', expect='The health checks.')
step('Open Legacy import.', 'Old guest records of the Lodge software can be loaded here, once.', target='btn:Run dry run', auto=['menu:Admin & Setup>Legacy import'], action='click', menu='Admin & Setup > Legacy import', expect='The Legacy import page opens.', check="ctx.page==='legacy-import'")
read('The import has a Run dry run button and a list of runs. A dry run reads the files and reports what would be loaded, per financial year, without changing anything. The training only explains it; the import is a one-time job done with the Owner.', 'A dry run catches problems before any data is changed.', target='btn:Run dry run', expect='The dry run button.')
step('Open Roadmap.', 'The roadmap shows what is planned next in HCC.', target='sel:main h1', auto=['menu:Admin & Setup>Roadmap'], action='click', menu='Admin & Setup > Roadmap', expect='The Roadmap page opens.', check="ctx.page==='roadmap'")
step('Lata, the Tech admin, signs in. She sees only People & Payroll and Admin & Setup: users, backup, system health and settings, and no hotel money.', 'The Tech admin keeps the system running without access to the guest or money data.', target='sel:.fit-home-grid', auto=['key:Escape', 'user:techadmin'], action='read', expect='Modules Home for Lata with two tiles.', check="ctx.uid==='techadmin'")
